  public InputStream input(){return new InputStream(){public int read(){throw new UnsupportedOperationException();}public int read(byte[]b,int o,int n)throws IOException{reads++;if(!fired){fired=true;if(mode.equals("after-read")){byte[]p=new byte[9];p[4]=2;p[5]=3;p[7]=3;p[8]=3;byte[]w=Mavlink.packet(0,p,0);w[5]=42;w[6]=1;int len=w[1]&255,c=Mavlink.crc(w,10+len,50);w[10+len]=(byte)c;w[11+len]=(byte)(c>>8);System.arraycopy(w,0,b,o,w.length);request();return w.length;}if(mode.equals("before-tick")){request();throw new SocketTimeoutException("MOCK_TIMEOUT");}if(mode.equals("read-error")){request();throw new IOException("MOCK_REAL_READ_ERROR");}if(mode.equals("background")){fg.set(false);owner.get().close("ACTIVITY_PAUSED");throw new SocketException("Socket closed");}}throw new SocketTimeoutException("MOCK_TIMEOUT");}};}
  public OutputStream output(){return new OutputStream(){public void write(int b){throw new UnsupportedOperationException();}public void write(byte[]b,int o,int n)throws IOException{writes++;if(!fired&&(mode.equals("during-send")||mode.equals("write-error"))){fired=true;request();if(mode.equals("write-error"))throw new IOException("MOCK_REAL_WRITE_ERROR");}}};}
  public boolean isClosed(){return closed;}public void close(){closed=true;}
  void run()throws Exception{File files=new File(root,mode);check(files.mkdir(),"fixturefiles");RunLifecycle.Clock clock=new RunLifecycle.Clock(){public long monotonicNs(){return System.nanoTime();}public long wallUtcMs(){return System.currentTimeMillis();}};NativeSegments.Sync sync=new NativeSegments.Sync(){public void file(FileDescriptor fd)throws IOException{fd.sync();}public void directory(File f)throws IOException{try(FileChannel c=FileChannel.open(f.toPath(),StandardOpenOption.READ)){c.force(true);}}};ControlOwner op=new ControlOwner(files,new ControlConfig(mode,ProfileFixture.specs()),clock,sync,fg::get,(id,s)->{finalState=s;},"touch-11111111-1111-1111-1111-111111111111",()->this);owner.set(op);op.start();Field field=ControlOwner.class.getDeclaredField("thread");field.setAccessible(true);Thread thread=(Thread)field.get(op);thread.join(4000);check(!thread.isAlive(),"ownerthreadnotclosed");check(closed,"FDnotclosed");check(finalState!=null&&finalState.contains("\"closed\":true"),"noclosedsession");if(mode.equals("read-error"))check(finalState.contains("MOCK_REAL_READ_ERROR"),"readIOerrorhiddenbyclose");else if(mode.equals("write-error"))check(finalState.contains("MOCK_REAL_WRITE_ERROR"),"writeIOerrorhiddenbyclose");else check(finalState.contains("\"firstFailure\":null"),"falsefailure:"+finalState);if(mode.equals("during-send"))check(writes==1,"newoperationsafterclose");if(mode.equals("background"))check(reads==1,"backgroundreadcontinued");}
